:root {
  --ink: #18343a;
  --paper: #fffdf6;
  --line: #b9d2c8;
  --mint: #bdebd7;
  --coral: #f36e55;
}

.valet-card {
  width: 440px;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  background-color: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 14px;
  color: var(--ink);
}

.valet-header {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 17px;
}

.valet-icon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  background-color: var(--mint);
  border-radius: 50%;
  font-size: 20px;
}

.valet-detail {
  margin: 0;
  padding-left: 14px;
  border-left: 1px solid var(--line);
  font-size: 14px;
}

.claim-code {
  margin-left: auto;
  padding: 8px 12px;
  border: 0;
  border-radius: 8px;
  background-color: var(--coral);
  color: var(--paper);
  font-size: 14px;
  font-weight: 700;
}
